mapper.select:
SELECT h.history_id, h.tag_id, t.tag_name, t.address, t.alarm_msg, t.level, t.plc_id, t.folder_id, f.folder_name, h.occur_time, h.clear_time, h.ack_time, h.ack_user, h.value_at_occur FROM tb_alarm_history h JOIN tb_alarm_tag t ON h.tag_id = t.tag_id JOIN tb_alarm_folder f ON t.folder_id = f.folder_id
AND t.tag_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY h.occur_time DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE tb_alarm_tag
SET tag_name = #{tagName}, address = #{address}, plc_id = #{plcId},
    alarm_msg = #{alarmMsg}, level = #{level}, enabled = #{enabled}
WHERE tag_id = #{tagId}

mapper.select:
SELECT DATE_FORMAT(h.occur_time, '%Y-%m-%d %H:00:00') AS bucket, COUNT(*) AS cnt
FROM tb_alarm_history h
WHERE h.occur_time >= #{from}
  AND h.occur_time < #{to}
GROUP BY bucket
ORDER BY bucket ASC
